import React, { useState } from 'react';
import { skillsData } from '../data/skillsData';

function Skills() {
  const [activeCategory, setActiveCategory] = useState('frontend');

  const SkillBar = ({ skill }) => (
    <div className="bg-gray-800/50 rounded-xl p-6 border border-gray-700/50 hover:border-[#6699CC]/50 transition-all duration-300">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center space-x-3">
          <span className="text-2xl">{skill.icon}</span>
          <h4 className="text-lg font-semibold text-white">{skill.name}</h4>
        </div>
        <span className="text-[#6699CC] font-bold">{skill.level}%</span>
      </div>

      <div className="w-full bg-gray-700 rounded-full h-3 mb-2">
        <div 
          className="bg-gradient-to-r from-[#6699CC] to-[#5C4DCE] h-3 rounded-full transition-all duration-1000 ease-out"
          style={{ width: `${skill.level}%` }}
        ></div>
      </div>

      <p className="text-gray-400 text-sm">{skill.experience}</p>
    </div>
  );

  return (
    <section id="skills" className="py-20 px-6 sm:px-8 lg:px-12">
      <div className="max-w-7xl mx-auto">
        {/* Section Header */}
        <div className="text-center mb-16">
          <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
            My <span className="text-[#6699CC]">Skills</span>
          </h2>
          <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
            A comprehensive overview of my technical expertise and the tools I use to bring ideas to life
          </p>
        </div>

        {/* Category Tabs */}
        <div className="flex flex-wrap justify-center gap-4 mb-12">
          {Object.entries(skillsData).map(([key, category]) => (
            <button
              key={key}
              onClick={() => setActiveCategory(key)}
              className={`px-6 py-3 rounded-full font-medium transition-all duration-300 flex items-center space-x-2 ${
                activeCategory === key
                  ? 'bg-[#6699CC] text-[#20262E]'
                  : 'bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 hover:text-white'
              }`}
            >
              <span className="text-xl">{category.icon}</span>
              <span>{category.title}</span>
            </button>
          ))}
        </div>

        {/* Skills Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {skillsData[activeCategory].skills.map((skill, index) => (
            <SkillBar key={index} skill={skill} />
          ))}
        </div>


      </div>
    </section>
  );
}

export default Skills;
